document.addEventListener("DOMContentLoaded",t=>{document.querySelectorAll("*[data-include]").forEach(t=>{const e=t.getAttribute("data-include"),n=t.getAttribute("data-update"),a=t.getAttribute("data-stop-when");let d;const r=()=>{fetch(e).then(e=>{e.text().then(e=>{t.innerHTML=e,null!==a&&e.trim()===a&&void 0!==d&&clearInterval(d)})})};if(r(),n){const t=parseInt(n,10);!isNaN(t)&&t>0&&(d=setInterval(r,1e3*t))}})});